('mcp-google-drive', 'mcp', 'Google Drive MCP Server', 'Google Drive MCP server — agents access, create, and search files across Google Drive and Google Docs.', 'Gives agents access to Google Drive: search files by name or content, read Google Docs/Sheets/Slides, create new documents, upload files, and manage folder structure. OAuth2 authenticated. Works with Hermes, Claude Desktop, and compatible MCP hosts.', 'file-storage', ARRAY['Claude','Open WebUI'], true, false, 'https://github.com/GoogleCloudPlatform/mcp-gdrive', 'Google', ARRAY['google-drive','files','documents','storage','mcp']),

('mcp-jira', 'mcp', 'Jira MCP Server', 'Jira MCP server — agents create tickets, update sprint boards, and query project backlogs in Jira.', 'Full Jira integration via MCP. Create and update issues, transition ticket status, add comments, query JQL filters, manage sprint boards, and generate sprint reports. Supports Jira Cloud and Jira Server. Ideal for DevOps and project management agents.', 'project-management', ARRAY['Claude','Open WebUI'], false, false, 'https://github.com/sooperset/mcp-atlassian', 'Community', ARRAY['jira','project-management','tickets','agile','mcp']),

('mcp-confluence', 'mcp', 'Confluence MCP Server', 'Confluence MCP server — agents search, read, and create Confluence documentation pages.', 'Connects agents to Confluence for documentation tasks. Search pages by keyword or label, read full page content, create new pages in designated spaces, update existing documentation, and navigate page hierarchies. Pairs well with the Jira MCP server for full Atlassian coverage.', 'documentation', ARRAY['Claude','Open WebUI'], false, false, 'https://github.com/sooperset/mcp-atlassian', 'Community', ARRAY['confluence','documentation','wiki','atlassian','mcp']),

