('mcp-aws-kb', 'mcp', 'AWS Knowledge Base MCP Server', 'AWS Bedrock Knowledge Base MCP server — agents query RAG knowledge bases hosted on AWS Bedrock.', 'Exposes AWS Bedrock Knowledge Bases as MCP tools. Agents can semantically query indexed documents stored in S3, retrieve cited passages, and use the results as context for responses. Supports multiple knowledge bases and fine-grained IAM access control.', 'knowledge-base', ARRAY['Claude'], false, false, 'https://github.com/aws-samples/bedrock-kb-mcp', 'AWS', ARRAY['aws','bedrock','rag','knowledge-base','mcp']),

('mcp-obsidian', 'mcp', 'Obsidian MCP Server', 'Obsidian vault MCP server — agents read, write, and search notes in local Obsidian vaults.', 'Gives AI agents access to Obsidian vaults. Read note content, search across vault by keyword or tag, create new notes with proper frontmatter, update existing notes, navigate links between notes, and manage folders. Perfect for personal knowledge management agents.', 'knowledge-base', ARRAY['Claude','Open WebUI'], true, true, 'https://github.com/MarkusPfundstein/mcp-obsidian', 'Community', ARRAY['obsidian','notes','pkm','markdown','mcp','vault']),

('mcp-discord', 'mcp', 'Discord MCP Server', 'Discord MCP server — agents send messages, read channels, and manage Discord server interactions.', 'Connects agents to Discord servers via bot token. Read channel message history, send messages to channels, create threads, react to messages, and manage roles. Useful for community management agents and Discord-based workflows. Requires Discord bot with appropriate permissions.', 'messaging', ARRAY['Claude','Open WebUI'], true, false, 'https://github.com/v-3/discordmcp', 'Community', ARRAY['discord','messaging','bot','community','mcp']),

